H = "Hakeem Force Academy"
QS = [
(H, "Which city was named as the capital of Pakistan in the Constitution of 1962?",
 ["Karachi", "Lahore", "Islamabad", "Peshawar"], 2,
 "The 1962 Constitution named the newly built city of Islamabad as the capital, with Rawalpindi serving as the interim capital while it was being built.",
 "Ayub Khan chose the site of Islamabad near General Headquarters at Rawalpindi.", -1),
(H, "Under which Article of the 1962 Constitution could the President promulgate Ordinances when the National Assembly was not in session?",
 ["Article 19", "Article 29", "Article 39", "Article 49"], 1,
 "Article 29 of the 1962 Constitution allowed the President to make an Ordinance with the same force as an Act when the Assembly was dissolved or not in session and immediate legislation was needed.",
 "Such an Ordinance covered only matters within the competence of the Central Legislature.", -1),
(H, "Under Article 226 of the 1962 Constitution, who was treated as the first President of Pakistan under that Constitution?",
 ["Iskander Mirza", "Field Marshal Muhammad Ayub Khan", "General Yahya Khan", "Ghulam Muhammad"], 1,
 "Article 226 (transitional provisions) provided that, following the referendum of February 1960, Field Marshal Muhammad Ayub Khan was to be the first President under the 1962 Constitution.",
 "The 1962 Constitution came into force on 8 June 1962.", -1),
(H, "Which Order, issued by General Yahya Khan on 30 March 1970, set the framework for the first general elections and for making a new constitution?",
 ["Provisional Constitution Order 1955", "Legal Framework Order 1970", "Interim Constitution Order 1972", "Revival of the Constitution Order 1985"], 1,
 "The Legal Framework Order of 30 March 1970 laid down the basis for the December 1970 elections and required the elected Assembly to frame a constitution within 120 days.",
 "The LFO also ended the One Unit scheme of West Pakistan on 1 July 1970.", -1),
(H, "In which month and year was the Constitution of 1962 abrogated?",
 ["March 1969", "June 1970", "July 1970", "December 1971"], 0,
 "General Yahya Khan imposed martial law and abrogated the 1962 Constitution on 25 March 1969.",
 "The 1962 Constitution had come into force on 8 June 1962.", 3422),
(H, "For approximately how many years did the Constitution of 1962 remain in force?",
 ["Three years", "Five years", "Seven years", "Ten years"], 2,
 "It was in force from 8 June 1962 until 25 March 1969, which is about seven years (nearly six years and nine months).",
 "It was Pakistan's second constitution.", -1),
(H, "Which system of government was introduced by the Constitution of 1962?",
 ["Parliamentary system", "Presidential system", "Military council system", "Provincial confederation"], 1,
 "The 1962 Constitution concentrated executive power in the President, who was both head of state and head of government, so critics called it a one-man show.",
 "The President was elected indirectly by Electoral College of Basic Democrats.", -1),
(H, "Who abrogated the Constitution of 1962?",
 ["General Tikka Khan", "General Agha Muhammad Yahya Khan", "General Muhammad Zia-ul-Haq", "Air Marshal Asghar Khan"], 1,
 "General Agha Muhammad Yahya Khan took over from Ayub Khan and abrogated the 1962 Constitution on 25 March 1969.",
 "Yahya Khan became President and Chief Martial Law Administrator.", 1636),
(H, "On which date was the Constitution of 1973 authenticated by the President of Pakistan?",
 ["23 March 1973", "12 May 1973", "12 April 1973", "14 August 1973"], 2,
 "The National Assembly passed the Constitution on 10 April 1973 and President Fazal Elahi Chaudhry authenticated it on 12 April 1973.",
 "The President who authenticated it was Fazal Elahi Chaudhry.", -1),
(H, "On which date did the Constitution of 1973 come into force?",
 ["23 March 1973", "12 April 1973", "14 August 1973", "23 March 1974"], 2,
 "The Constitution was enforced on 14 August 1973, the Independence Day, after being authenticated on 12 April 1973.",
 "Zulfikar Ali Bhutto became Prime Minister under it.", -1),
(H, "How many Articles does the Constitution of 1973 contain?",
 ["250", "270", "280", "285"], 2,
 "The Constitution of 1973 has 280 Articles divided into 12 Parts.",
 "Articles added by amendments carry letters, for example Article 140A and Article 10A.", -1),
(H, "On which date was the Objectives Resolution passed by the Constituent Assembly of Pakistan?",
 ["12 January 1949", "12 February 1949", "12 March 1949", "12 April 1949"], 2,
 "The Objectives Resolution was passed on 12 March 1949, moved by Liaquat Ali Khan.",
 "It became the Preamble of the 1973 Constitution.", 4333),
(H, "According to the Objectives Resolution, sovereignty over the entire Universe belongs to whom?",
 ["The people of Pakistan", "Almighty Allah alone", "The Government of Pakistan", "The Head of State"], 1,
 "The Objectives Resolution states that sovereignty over the entire Universe belongs to Almighty Allah alone.",
 "It adds that the authority is delegated to the State through its people as a sacred trust.", -1),
(H, "According to the Objectives Resolution, the authority exercised by the people of Pakistan within limits set by Allah is a what?",
 ["Sacred trust", "Absolute right", "Political privilege", "Temporary duty"], 0,
 "The Resolution says the authority to be exercised by the people within the limits prescribed by Allah is a sacred trust.",
 "The Resolution says the State shall exercise its powers through the chosen representatives of the people.", -1),
(H, "According to the Objectives Resolution, through whom shall the State exercise its powers and authority?",
 ["Military rulers", "The chosen representatives of the people", "Hereditary leaders", "Foreign advisers"], 1,
 "The Objectives Resolution says the State shall exercise its powers and authority through the chosen representatives of the people.",
 "It also promises democracy, freedom, equality, tolerance and social justice as enunciated by Islam.", -1),
(H, "According to the Objectives Resolution, how shall Muslims be enabled to order their lives?",
 ["In a secular manner", "In accordance with the teachings and requirements of Islam", "According to tribal customs", "As decided by each province"], 1,
 "The Resolution says Muslims shall be enabled to order their lives in the individual and collective spheres in accordance with the teachings and requirements of Islam as set out in the Quran and Sunnah.",
 "The Resolution was moved in the Constituent Assembly by Prime Minister Liaquat Ali Khan.", -1),
(H, "According to the Objectives Resolution, what freedom shall be given to minorities?",
 ["To profess and practise their religions and develop their cultures freely", "To follow only the teachings of Islam", "To live as decided by government policy", "To form separate states"], 0,
 "The Resolution says adequate provision shall be made for minorities freely to profess and practise their religions and develop their cultures.",
 "It also promises to safeguard the legitimate interests of minorities and backward classes.", -1),
(H, "According to the Objectives Resolution, the independence of the judiciary shall be what?",
 ["Fully secured", "Placed under the executive", "Reviewed every ten years", "Limited by Parliament"], 0,
 "The Resolution states that the independence of the judiciary shall be fully secured.",
 "It also says fundamental rights, including equality of status and opportunity, shall be guaranteed.", -1),
(H, "According to the Objectives Resolution, Pakistan will make its full contribution towards what?",
 ["Military alliances", "International peace and progress and the happiness of humanity", "Trade expansion only", "Regional dominance"], 1,
 "The Resolution says the people of Pakistan should attain their rightful place among nations and make their full contribution towards international peace and progress and the happiness of humanity.",
 "This is the closing aim stated in the Resolution and in the Preamble.", -1),
(H, "In what form was the Objectives Resolution placed in the Constitution of 1973 as originally enacted?",
 ["Preamble", "Annexure", "First Schedule", "Article 1"], 0,
 "In the original 1973 Constitution the Objectives Resolution was the Preamble. It became a substantive part later through Article 2A.",
 "Article 2A was inserted by the Eighth Amendment in 1985.", -1),
(H, "What name does Article 1 of the Constitution of 1973 give to Pakistan?",
 ["Republic of Pakistan", "Islamic Republic of Pakistan", "Federation of Pakistan", "Islamic Federation of Pakistan"], 1,
 "Article 1(1) says Pakistan shall be a Federal Republic to be known as the Islamic Republic of Pakistan.",
 "The name Islamic Republic was first used in the 1956 Constitution.", -1),
(H, "After the 25th Amendment of 2018, what do the territories of Pakistan under Article 1 comprise?",
 ["Four provinces, FATA and the Federal Capital", "Four provinces and Gilgit-Baltistan only", "The provinces of Balochistan, Khyber Pakhtunkhwa, Punjab and Sindh, and the Islamabad Capital Territory (plus such other territories as may be included)", "Four provinces, Azad Kashmir and Islamabad only"], 2,
 "The 25th Amendment (2018) merged FATA into Khyber Pakhtunkhwa and removed it from Article 1, so Article 1(2) now lists four provinces and the Islamabad Capital Territory. The older answer with FATA is outdated.",
 "Article 1(2)(c) also covers such States and territories as are or may be included in Pakistan.", -1),
(H, "Under which Article of the 1973 Constitution is Islam declared the State religion of Pakistan?",
 ["Article 1", "Article 2", "Article 2A", "Article 3"], 1,
 "Article 2 states that Islam shall be the State religion of Pakistan.",
 "Article 2A makes the Objectives Resolution a substantive part of the Constitution.", 1980),
(H, "Which Article of the 1973 Constitution makes the Objectives Resolution a substantive part of the Constitution?",
 ["Article 2", "Article 2A", "Article 3", "Article 227"], 1,
 "Article 2A states that the principles and provisions of the Objectives Resolution (Annex) are made substantive part of the Constitution and have effect accordingly.",
 "It was inserted in 1985 through the Eighth Amendment.", -1),
(H, "Under Article 5(1) of the Constitution of 1973, loyalty to whom is the basic duty of every citizen?",
 ["The State", "The ruling government", "The political party in power", "The President"], 0,
 "Article 5(1) says loyalty to the State is the basic duty of every citizen.",
 "Article 5 is in Part I of the Constitution.", -1),
(H, "Article 5(2) of the Constitution of 1973 describes obedience to the Constitution and law as the what of every citizen?",
 ["Inviolable obligation", "Optional right", "Voluntary service", "Conditional duty"], 0,
 "Article 5(2) says obedience to the Constitution and law is the inviolable obligation of every citizen wherever he may be and of every other person within Pakistan.",
 "Article 5(1) makes loyalty to the State the basic duty of every citizen.", -1),
(H, "A person who abrogates, subverts, suspends or holds in abeyance the Constitution by force or unconstitutional means is guilty of what under Article 6?",
 ["High treason", "Sedition", "Felony", "Contempt of court"], 0,
 "Article 6(1) says any person who abrogates or subverts the Constitution by use of force or show of force or other unconstitutional means is guilty of high treason.",
 "The words 'suspends or holds in abeyance' were added by the 18th Amendment in 2010.", -1),
(H, "Under Article 6(3) of the Constitution, who is empowered to provide the punishment for persons found guilty of high treason?",
 ["Majlis-e-Shoora (Parliament)", "The Supreme Court", "The President", "The Federal Shariat Court"], 0,
 "Article 6(3) says the Majlis-e-Shoora (Parliament) shall by law provide for the punishment of persons found guilty of high treason.",
 "The High Treason (Punishment) Act 1973 was passed under this Article.", -1),
(H, "In which Article of the 1973 Constitution is the State defined for the purposes of Fundamental Rights?",
 ["Article 6", "Article 7", "Article 8", "Article 9"], 1,
 "Article 7 defines the State as the Federal Government, Parliament, a Provincial Government, a Provincial Assembly and local authorities.",
 "Article 8 follows and deals with laws inconsistent with Fundamental Rights.", -1),
(H, "Which Articles of the 1973 Constitution contain the Principles of Policy?",
 ["Articles 18 to 28", "Articles 29 to 40", "Articles 41 to 50", "Articles 8 to 28"], 1,
 "Chapter 2 of Part II, Articles 29 to 40, sets out the Principles of Policy.",
 "Principles of Policy are not enforceable in court, unlike the Fundamental Rights.", -1),
(H, "Under Article 8 of the 1973 Constitution, a law that is inconsistent with the Fundamental Rights is what?",
 ["Void to the extent of the inconsistency", "Illegal but enforceable", "Valid for ten years", "Valid unless the President objects"], 0,
 "Article 8 says any law inconsistent with or in derogation of the Fundamental Rights shall, to the extent of such inconsistency, be void.",
 "Article 8 itself falls in Chapter 1 of Part II.", -1),
(H, "Under which Article of the 1973 Constitution is no person to be deprived of life or liberty save in accordance with law?",
 ["Article 8", "Article 9", "Article 10", "Article 11"], 1,
 "Article 9 (security of person) says no person shall be deprived of life or liberty save in accordance with law.",
 "The Supreme Court has read the right to life broadly to include a healthy environment.", -1),
(H, "Which Articles of the 1973 Constitution deal with the Fundamental Rights?",
 ["Articles 8 to 28", "Articles 8 to 30", "Articles 8 to 32", "Articles 1 to 28"], 0,
 "Chapter 1 of Part II, Articles 8 to 28, contains the Fundamental Rights.",
 "Articles 29 to 40 contain the Principles of Policy.", -1),
(H, "What is Chapter 1 of Part II of the 1973 Constitution (Articles 8 to 28) called?",
 ["Fundamental Rights", "Principles of Policy", "Directive Duties", "Citizens' Charter"], 0,
 "Chapter 1 of Part II is titled Fundamental Rights, the rights guaranteed by the Constitution and enforceable in court.",
 "Chapter 2 of Part II is titled Principles of Policy.", -1),
(H, "Safeguards as to arrest and detention are provided in which Article of the 1973 Constitution?",
 ["Article 8", "Article 10", "Article 12", "Article 14"], 1,
 "Article 10 gives safeguards on arrest and detention, including the right to be told the grounds and to appear before a magistrate within 24 hours.",
 "Article 10A adds the right to a fair trial.", -1),
(H, "Article 10A of the 1973 Constitution deals with which right?",
 ["Right to fair trial and due process", "Right to free education", "Right to information", "Freedom of the press"], 0,
 "Article 10A guarantees the right to fair trial and due process in the determination of civil rights and criminal charges.",
 "Article 25A deals with free and compulsory education.", -1),
(H, "Through which amendment was the right to fair trial (Article 10A) added to the Fundamental Rights?",
 ["8th Amendment 1985", "17th Amendment 2003", "18th Amendment 2010", "21st Amendment 2015"], 2,
 "Article 10A was inserted by the 18th Amendment of 2010.",
 "The 18th Amendment also inserted Article 19A (right to information) and Article 25A (right to education).", -1),
(H, "Under which Article of the 1973 Constitution are slavery and forced labour prohibited?",
 ["Article 11", "Article 12", "Article 13", "Article 14"], 0,
 "Article 11 prohibits slavery, forced labour and the employment of children below fourteen in factories, mines or hazardous work.",
 "Article 11 also forbids trafficking in human beings.", -1),
(H, "Article 12 of the 1973 Constitution gives protection against what?",
 ["Retrospective punishment", "Double punishment", "Torture", "Illegal search"], 0,
 "Article 12 gives protection against retrospective punishment, meaning no one can be punished for an act that was not an offence when it was done.",
 "Article 13 protects against double punishment and self-incrimination.", -1),
(H, "Article 13 of the 1973 Constitution gives protection against what?",
 ["Retrospective punishment", "Double punishment and self-incrimination", "Arbitrary arrest", "Forced labour"], 1,
 "Article 13 says no person shall be punished more than once for the same offence nor be compelled to be a witness against himself.",
 "Article 12 gives protection against retrospective punishment.", -1),
(H, "Under which provision of the 1973 Constitution is no person to be subjected to torture for extracting evidence?",
 ["Article 14(1)", "Article 14(2)", "Article 13", "Article 15"], 1,
 "Article 14(2) says no person shall be subjected to torture for the purpose of extracting evidence.",
 "Article 14(1) says the dignity of man and the privacy of home shall be inviolable.", -1),
(H, "Which freedom is guaranteed by Article 15 of the 1973 Constitution?",
 ["Freedom of speech", "Freedom of movement", "Freedom of association", "Freedom of assembly"], 1,
 "Article 15 guarantees every citizen the right to remain in, enter and move freely throughout Pakistan and settle in any part of it, subject to law.",
 "Freedom of speech is in Article 19.", -1),
(H, "Under which Article of the 1973 Constitution is freedom of assembly guaranteed?",
 ["Article 15", "Article 16", "Article 17", "Article 18"], 1,
 "Article 16 gives every citizen the right to assemble peacefully and without arms, subject to reasonable restrictions imposed by law in the interest of public order.",
 "Article 17 covers freedom of association.", -1),
(H, "Which freedom is provided in Article 17 of the 1973 Constitution?",
 ["Freedom of assembly", "Freedom of association", "Freedom of movement", "Freedom of speech"], 1,
 "Article 17 gives every citizen the right to form associations or unions and to form or be a member of a political party, subject to restrictions in the interest of sovereignty and integrity of Pakistan.",
 "Article 16 covers freedom of assembly.", -1),
(H, "Which freedom is guaranteed by Article 18 of the 1973 Constitution?",
 ["Freedom of the press", "Freedom of trade, business or profession", "Freedom of religion", "Freedom of movement"], 1,
 "Article 18 gives every citizen the right to enter upon any lawful profession or occupation and to conduct any lawful trade or business.",
 "Article 20 covers freedom to profess religion.", -1),
(H, "Under which Article of the 1973 Constitution does every citizen have the right of access to information in matters of public importance?",
 ["Article 18", "Article 19", "Article 19A", "Article 20"], 2,
 "Article 19A, inserted by the 18th Amendment in 2010, gives every citizen the right of access to information in all matters of public importance, subject to reasonable restrictions imposed by law.",
 "Article 19 itself covers freedom of speech.", -1),
(H, "Under which Article of the 1973 Constitution is there safeguard against taxation for the purposes of any particular religion?",
 ["Article 20", "Article 21", "Article 22", "Article 23"], 1,
 "Article 21 says no person shall be compelled to pay any special tax the proceeds of which are to be spent on the propagation or maintenance of any religion other than his own.",
 "Article 20 gives freedom to profess religion and to manage religious institutions.", -1),
]
